int main() {
    const char* api_url = "https://example.com/api/user";
    const char* user_id = "aBc123";

    // Using snprintf to construct the URL in a single operation
    size_t total_length = strlen(api_url) + 1 + strlen(user_id) + 1;
    char* url = malloc(total_length);

    if (url != NULL) {
        snprintf(url, total_length, "%s/%s", api_url, user_id);
        printf("Generated URL: %s\n", url);
        free(url);
    } else {
        printf("Memory allocation failed\n");
    }

    return 0;
}
